; Function: record
_fn_record:

    ; int_arith.xt — regression test for integer arithmetic and
    ; comparison across the six built-in integer types: u8, i8, u16,
    ; i16, u32, i32.
    ;
    ; Each test block computes a value via ordinary xtc expression
    ; syntax, copies the result bytes into r0..r4, writes the
    ; expected bytes into e0..e4, and calls record() to compare
    ; them byte-wise and emit "T<n> PASS" or "T<n> FAIL" via
    ; Stdio.printf. The Makefile harness (`make fixtures`) greps
    ; xts -d output for PASS/FAIL and reports per-configuration
    ; totals.
    ;
    ; Scope (first pass):
    ;   * Arithmetic: + - * / %
    ;   * Compare:    < > <= >= == !=
    ;   * One cross-width example: u8 widened to u16 in an addition.
    ;
    ; All six types get coverage of every operator. For narrow types
    ; (≤ 2 bytes) the unused record bytes are zero-padded; for u32/i32
    ; all four bytes are stored. Signed types pick a case that would
    ; come out with the wrong sign if the codegen were treating the
    ; value as unsigned.
    ;
    ; record() is called silently on pass — only mismatches print a line.
    ; This keeps total output under the Atari 40×24 screen that `xts -d`
    ; captures, so fixtures with >24 tests still fit. main() finishes with
    ; a `DONE <N>` terminator so the harness can tell the program actually
    ; ran to completion.
    ; testCount = testCount + 1;
    LDA $98 ; testCount
    CLC
    ADC #$01
    STA $98 ; testCount

    ; if (r0 != e0 || r1 != e1 || r2 != e2 || r3 != e3 || r4 != e4) {
    LDA $8E ; r0
    CMP $93
    BEQ _L0080
    JMP _L0081
_L0080:
    LDA $8F ; r1
    CMP $94
    BEQ _L0079
_L0081:
    JMP _L0082
_L0079:
    LDA $90 ; r2
    CMP $95
    BEQ _L0078
_L0082:
    JMP _L0083
_L0078:
    LDA $91 ; r3
    CMP $96
    BEQ _L0077
_L0083:
    JMP _L0084
_L0077:
    LDA $92 ; r4
    CMP $97
    BEQ _L0075
_L0084:

    ; Stdio.printf("T%u FAIL\n", testCount);
