; class-id → parent-id table (for `as` / `as?` downcast walks)
__class_parent:
    .BYTE $00,$00,$00

; Runtime library routines

; u16Div — unsigned 16-bit divide
; Input:  $B0,$B1 = dividend (u16), $B2,$B3 = divisor (u16)
; Output: $B0,$B1 = quotient (u16), $B2,$B3 = remainder (u16)

u16Div:
    LDA #$00
    STA $B4 ; remainder lo
    STA $B5 ; remainder hi
    LDX #16
.loop:
    ASL $B0
    ROL $B1 ; shift dividend left
    ROL $B4
    ROL $B5 ; shift into remainder
    ; Compare remainder with divisor
    LDA $B4
    CMP $B2
    LDA $B5
    SBC $B3
    BCC .no_sub
    ; remainder >= divisor: subtract
    LDA $B4
    SEC
    SBC $B2
    STA $B4
    LDA $B5
    SBC $B3
    STA $B5
    INC $B0 ; set quotient bit
.no_sub:
    DEX
    BNE .loop
    LDA $B4 : STA $B2
    LDA $B5 : STA $B3
    RTS


; i16Div — signed 16-bit divide
; Input:  $B0,$B1 = dividend (i16), $B2,$B3 = divisor (i16)
; Output: $B0,$B1 = quotient (i16), $B2,$B3 = remainder (i16)

i16Div:
    LDA #$00
    STA $B8
    LDA $B1
    BPL .op1_pos
    JSR .neg16_b0
    INC $B8
.op1_pos:
    LDA $B3
    BPL .op2_pos
    JSR .neg16_b2
    INC $B8
.op2_pos:
    JSR u16Div
    LDA $B8
    AND #$01
    BEQ .done
    JSR .neg16_b0
.done:
    RTS

.neg16_b0:
    LDA $B0 : EOR #$FF : STA $B0
    LDA $B1 : EOR #$FF : STA $B1
    INC $B0
    BNE .ret : INC $B1
.ret:
    RTS

.neg16_b2:
    LDA $B2 : EOR #$FF : STA $B2
    LDA $B3 : EOR #$FF : STA $B3
    INC $B2
    BNE .ret2 : INC $B3
.ret2:
    RTS


; i16Mod — signed 16-bit modulus (C99: sign of dividend)
; Input:  $B0,$B1 = dividend, $B2,$B3 = divisor
; Output: $B0,$B1 = remainder
;
; i16Div returns the unsigned remainder in $B2,$B3 with sign
; information discarded. C99 says `%` takes the sign of the
; dividend, so we save the dividend's sign bit (high byte of $B1)
; before calling i16Div and negate the remainder after if the
; dividend was negative.

i16Mod:
    LDA $B1 ; dividend high byte — bit 7 = sign
    PHA
    JSR i16Div
    LDA $B2 : STA $B0
    LDA $B3 : STA $B1
    PLA
    BPL .mod_done
    ; Negate 16-bit $B0,$B1
    SEC
    LDA #$00 : SBC $B0 : STA $B0
    LDA #$00 : SBC $B1 : STA $B1
.mod_done:
    RTS


; u16Mul — unsigned 16-bit multiply
; Input:  $B0,$B1 = operand1 (u16 little-endian)
;         $B2,$B3 = operand2 (u16 little-endian)
; Output: $B0,$B1,$B2,$B3 = result (u32 little-endian)
;
; Method: shift-and-add (16x16 -> 32)

u16Mul:
    ; result in $B4-$B7, then copy to $B0-$B3
    LDA #$00
    STA $B4
    STA $B5
    STA $B6
    STA $B7
    LDX #16 ; 16 bits
.loop:
    LSR $B3
    ROR $B2 ; shift multiplier right
    BCC .no_add
    CLC
    LDA $B4
    ADC $B0
    STA $B4
    LDA $B5
    ADC $B1
    STA $B5
    LDA $B6
    ADC #$00
    STA $B6
    LDA $B7
    ADC #$00
    STA $B7
.no_add:
    ASL $B0
    ROL $B1 ; shift multiplicand left
    DEX
    BNE .loop
    ; Copy result
    LDA $B4 : STA $B0
    LDA $B5 : STA $B1
    LDA $B6 : STA $B2
    LDA $B7 : STA $B3
    RTS


; i16Mul — signed 16-bit multiply → i32
; Input:  $B0,$B1 = operand1 (i16), $B2,$B3 = operand2 (i16)
; Output: $B0,$B1,$B2,$B3 = result (i32 little-endian)

i16Mul:
    LDA #$00
    STA $B8 ; sign flag
    ; Make operand1 positive
    LDA $B1
    BPL .op1_pos
    JSR .neg16_b0
    INC $B8
.op1_pos:
    LDA $B3
    BPL .op2_pos
    JSR .neg16_b2
    INC $B8
.op2_pos:
    JSR u16Mul
    LDA $B8
    AND #$01
    BEQ .done
    ; Negate 32-bit result
    LDA $B0 : EOR #$FF : STA $B0
    LDA $B1 : EOR #$FF : STA $B1
    LDA $B2 : EOR #$FF : STA $B2
    LDA $B3 : EOR #$FF : STA $B3
    INC $B0
    BNE .done
    INC $B1
    BNE .done
    INC $B2
    BNE .done
    INC $B3
.done:
    RTS

.neg16_b0:
    LDA $B0 : EOR #$FF : STA $B0
    LDA $B1 : EOR #$FF : STA $B1
    INC $B0
    BNE .neg16_b0_done
    INC $B1
.neg16_b0_done:
    RTS

.neg16_b2:
    LDA $B2 : EOR #$FF : STA $B2
    LDA $B3 : EOR #$FF : STA $B3
    INC $B2
    BNE .neg16_b2_done
    INC $B3
.neg16_b2_done:
    RTS


; u32Div — unsigned 32-bit divide
; Input:  $B0-$B3 = dividend, $B4-$B7 = divisor
; Output: $B0-$B3 = quotient, $B4-$B7 = remainder

u32Div:
    LDA #$00
    STA $B8 : STA $B9 : STA $BA : STA $BB  ; remainder = 0
    LDX #32
.loop:
    ASL $B0 : ROL $B1 : ROL $B2 : ROL $B3  ; shift dividend left
    ROL $B8 : ROL $B9 : ROL $BA : ROL $BB  ; into remainder
    ; Compare remainder >= divisor
    SEC
    LDA $B8 : SBC $B4
    PHA
    LDA $B9 : SBC $B5
    PHA
    LDA $BA : SBC $B6
    PHA
    LDA $BB : SBC $B7
    BCC .no_sub
    ; Remainder >= divisor, commit subtraction
    STA $BB
    PLA : STA $BA
    PLA : STA $B9
    PLA : STA $B8
    INC $B0 ; set quotient bit
    JMP .next
.no_sub:
    PLA : PLA : PLA ; discard tentative results
.next:
    DEX
    BNE .loop
    ; Copy remainder to $B4-$B7
    LDA $B8 : STA $B4
    LDA $B9 : STA $B5
    LDA $BA : STA $B6
    LDA $BB : STA $B7
    RTS


; i32Div — signed 32-bit divide
; Input:  $B0-$B3 = dividend, $B4-$B7 = divisor
; Output: $B0-$B3 = quotient, $B4-$B7 = remainder

i32Div:
    LDA #$00
    STA $BC
    LDA $B3
    BPL .op1_pos
    JSR i32Mul.neg32_b0
    INC $BC
.op1_pos:
    LDA $B7
    BPL .op2_pos
    JSR i32Mul.neg32_b4
    INC $BC
.op2_pos:
    JSR u32Div
    LDA $BC
    AND #$01
    BEQ .done
    JSR i32Mul.neg32_b0
.done:
    RTS


; i32Mod — signed 32-bit modulus (C99: sign of dividend)
; Input:  $B0-$B3 = dividend, $B4-$B7 = divisor
; Output: $B0-$B3 = remainder
;
; i32Div returns the unsigned remainder in $B4-$B7 with sign
; information discarded. C99 says `%` takes the sign of the
; dividend, so we save the dividend's sign bit (high byte of $B3)
; before calling i32Div and negate the remainder after if the
; dividend was negative.

i32Mod:
    LDA $B3 ; dividend top byte — bit 7 = sign
    PHA
    JSR i32Div
    LDA $B4 : STA $B0
    LDA $B5 : STA $B1
    LDA $B6 : STA $B2
    LDA $B7 : STA $B3
    PLA
    BPL .mod_done
    ; Negate 32-bit $B0-$B3
    SEC
    LDA #$00 : SBC $B0 : STA $B0
    LDA #$00 : SBC $B1 : STA $B1
    LDA #$00 : SBC $B2 : STA $B2
    LDA #$00 : SBC $B3 : STA $B3
.mod_done:
    RTS


; u32Mul — unsigned 32-bit multiply
; Input:  $B0-$B3 = operand1 (u32), $B4-$B7 = operand2 (u32)
; Output: $B0-$B3 = result low 32 bits (u32)
; Note:   upper 32 bits of 64-bit product are discarded.
;
; Method: shift-and-add

; Temporaries: $B8-$BB = accumulator
u32Mul:
    LDA #$00
    STA $B8 : STA $B9 : STA $BA : STA $BB
    LDX #32
.loop:
    LSR $B7 : ROR $B6 : ROR $B5 : ROR $B4  ; shift multiplier right
    BCC .no_add
    CLC
    LDA $B8 : ADC $B0 : STA $B8
    LDA $B9 : ADC $B1 : STA $B9
    LDA $BA : ADC $B2 : STA $BA
    LDA $BB : ADC $B3 : STA $BB
.no_add:
    ASL $B0 : ROL $B1 : ROL $B2 : ROL $B3  ; shift multiplicand left
    DEX
    BNE .loop
    LDA $B8 : STA $B0
    LDA $B9 : STA $B1
    LDA $BA : STA $B2
    LDA $BB : STA $B3
    RTS


; i32Mul — signed 32-bit multiply
; Input:  $B0-$B3 = operand1 (i32), $B4-$B7 = operand2 (i32)
; Output: $B0-$B3 = result (i32)
; Method: negate if needed, unsigned multiply, negate result if needed

i32Mul:
    LDA #$00
    STA $BC ; sign flag
    LDA $B3
    BPL .op1_pos
    JSR .neg32_b0
    INC $BC
.op1_pos:
    LDA $B7
    BPL .op2_pos
    JSR .neg32_b4
    INC $BC
.op2_pos:
    JSR u32Mul
    LDA $BC
    AND #$01
    BEQ .done
    JSR .neg32_b0
.done:
    RTS

.neg32_b0:
    LDA $B0 : EOR #$FF : STA $B0
    LDA $B1 : EOR #$FF : STA $B1
    LDA $B2 : EOR #$FF : STA $B2
    LDA $B3 : EOR #$FF : STA $B3
    INC $B0
    BNE .neg0_done : INC $B1
    BNE .neg0_done : INC $B2
    BNE .neg0_done : INC $B3
.neg0_done:
    RTS

.neg32_b4:
    LDA $B4 : EOR #$FF : STA $B4
    LDA $B5 : EOR #$FF : STA $B5
    LDA $B6 : EOR #$FF : STA $B6
    LDA $B7 : EOR #$FF : STA $B7
    INC $B4
    BNE .neg4_done : INC $B5
    BNE .neg4_done : INC $B6
    BNE .neg4_done : INC $B7
.neg4_done:
    RTS


; u8Div — unsigned 8-bit divide
; Input:  $B0 = dividend (u8), $B1 = divisor (u8)
; Output: $B0 = quotient (u8), $B1 = remainder (u8)
;
; Uses: A, X

u8Div:
    LDA #$00 ; remainder
    LDX #8 ; 8 bits
.loop:
    ASL $B0 ; shift dividend left, MSB into carry
    ROL A ; shift carry into remainder
    CMP $B1 ; compare remainder with divisor
    BCC .no_sub
    SBC $B1 ; subtract divisor from remainder
    INC $B0 ; set quotient bit
.no_sub:
    DEX
    BNE .loop
    STA $B1 ; store remainder
    RTS


; i8Div — signed 8-bit divide
; Input:  $B0 = dividend (i8), $B1 = divisor (i8)
; Output: $B0 = quotient (i8), $B1 = remainder (i8)

i8Div:
    LDA #$00
    STA $B2 ; sign flag
    LDA $B0
    BPL .op1_pos
    EOR #$FF
    CLC
    ADC #$01
    STA $B0
    INC $B2
.op1_pos:
    LDA $B1
    BPL .op2_pos
    EOR #$FF
    CLC
    ADC #$01
    STA $B1
    INC $B2
.op2_pos:
    JSR u8Div
    LDA $B2
    AND #$01
    BEQ .done
    LDA $B0
    EOR #$FF
    CLC
    ADC #$01
    STA $B0
.done:
    RTS


; i8Mod — signed 8-bit modulus (C99: sign of dividend)
; Input:  $B0 = dividend (i8), $B1 = divisor (i8)
; Output: $B0 = remainder (i8)
;
; i8Div returns the unsigned remainder in $B1 with the sign
; information already discarded (i8Div negates both operands to
; absolute before calling u8Div). To get C99 semantics we stash
; the dividend's sign bit on the hw stack before calling i8Div,
; then negate the remainder after if the dividend was negative.

i8Mod:
    LDA $B0 ; dividend — sign bit in bit 7
    PHA
    JSR i8Div
    LDA $B1 ; unsigned remainder from i8Div
    STA $B0
    PLA
    BPL .done ; dividend was >= 0 → remainder already correct
    ; Negate remainder
    SEC
    LDA #$00
    SBC $B0
    STA $B0
.done:
    RTS


; u8Mul — unsigned 8-bit multiply
; Input:  $B0 = operand1 (u8), $B1 = operand2 (u8)
; Output: $B0 = result low byte (u8), $B1 = result high byte (u8)
;         Together they form a u16 product.
;
; Uses: A, X
; Method: shift-and-add

u8Mul:
    LDA #$00
    LDX #8 ; 8 bits to process
    CLC
.loop:
    ROR $B1 ; shift multiplier right, bit 0 into carry
    BCC .no_add
    CLC
    ADC $B0 ; add multiplicand if bit was set
.no_add:
    ROR A ; shift partial product right (high byte)
    DEX
    BNE .loop
    ROR $B1 ; final shift of low byte
    STA $B0 ; A had the low partial; swap
    ; Actually the result high byte was shifted into $B1
    ; and the low byte is now in A → store properly
    TAY
    LDA $B1
    STA $B0 ; low byte of result
    STY $B1 ; high byte of result
    RTS


; i8Mul — signed 8-bit multiply
; Input:  $B0 = operand1 (i8), $B1 = operand2 (i8)
; Output: $B0 = result low byte (i16 low), $B1 = result high byte (i16 high)
;
; Method: convert to unsigned, multiply, fix sign

i8Mul:
    LDA #$00
    STA $B2 ; sign flag
    LDA $B0
    BPL .op1_pos
    EOR #$FF
    CLC
    ADC #$01
    STA $B0
    INC $B2 ; flip sign
.op1_pos:
    LDA $B1
    BPL .op2_pos
    EOR #$FF
    CLC
    ADC #$01
    STA $B1
    INC $B2
.op2_pos:
    JSR u8Mul ; unsigned multiply
    LDA $B2
    AND #$01 ; odd = negative result
    BEQ .done
    ; Negate 16-bit result
    LDA $B0
    EOR #$FF
    CLC
    ADC #$01
    STA $B0
    LDA $B1
    EOR #$FF
    ADC #$00
    STA $B1
.done:
    RTS


; u16Mod — unsigned 16-bit modulus
; Input:  $B0,$B1 = dividend (u16), $B2,$B3 = divisor (u16)
; Output: $B0,$B1 = remainder (u16)

u16Mod:
    JSR u16Div
    LDA $B2 : STA $B0
    LDA $B3 : STA $B1
    RTS


; u32Mod — unsigned 32-bit modulus
; Input:  $B0-$B3 = dividend, $B4-$B7 = divisor
; Output: $B0-$B3 = remainder

u32Mod:
    JSR u32Div
    LDA $B4 : STA $B0
    LDA $B5 : STA $B1
    LDA $B6 : STA $B2
    LDA $B7 : STA $B3
    RTS


; u8Mod — unsigned 8-bit modulus
; Input:  $B0 = dividend (u8), $B1 = divisor (u8)
; Output: $B0 = remainder (u8)
;
; Uses u8Div then moves remainder to $B0.

u8Mod:
    JSR u8Div
    LDA $B1
    STA $B0
    RTS


; _heap_alloc: allocate A bytes from heap (grows downward)
;   Entry: A = byte count
;   Exit:  A/X = pointer to allocated area (lo/hi)
;   Decrements HP by A, zero-fills the area, returns new HP.
_heap_alloc:
    STA $84
    SEC
    LDA $86
    SBC $84
    STA $86
    LDA $87
    SBC #$00
    STA $87
    LDY $84
    BEQ _ha_done
    LDA #$00
_ha_zero:
    DEY
    STA ($86),Y
    CPY #$00
    BNE _ha_zero
_ha_done:
    LDA $86
    LDX $87
    RTS

; Static class data
__sdata_Stdio:
    .BYTE $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
__sinit_Stdio:
    .BYTE $00

stack_low:
; xtc software stack grows upward from here toward heap_top

